{
  "name": "openai",
  "version": "7.45.0",
  "description": "The official TypeScript library for the OpenAI API",
  "author": "OpenAI <support@openai.com>",
  "types": "dist/index.d.ts",
  "main": "dist/index.js",
  "type": "commonjs",
  "repository": "github:openai/openai-node",
  "license": "Apache-2.0",
  "packageManager": "pnpm@11.5.1",
  "files": [
    "**/*"
  ],
  "private": false,
  "publishConfig": {
    "access": "public"
  },
  "engines": {
    "node": ">=22.0.0"
  },
  "scripts": {
    "test": "./scripts/test",
    "test:unit": "vitest run --config vitest.config.mts",
    "test:generated": "OPENAI_TEST_SUITE=generated ./scripts/test",
    "test:live:bedrock": "jest --config jest.live.config.ts --runInBand tests/live/bedrock.live.test.ts",
    "test:live:x509": "pnpm build && node --input-type=module < examples/mtls/x509-workload-identity.mjs",
    "bench": "vitest bench --run --config vitest.bench.config.mts",
    "bench:json": "vitest bench --run --config vitest.bench.config.mts --reporter=default --reporter=json --outputFile=benchmark-results.json",
    "build": "./scripts/build",
    "prepublishOnly": "echo 'to publish, run pnpm build && (cd dist; npm publish)' && exit 1",
    "format": "./scripts/format",
    "prepare": "if ./scripts/utils/check-is-in-git-install.sh; then ./scripts/build && ./scripts/utils/git-swap.sh; fi",
    "tsn": "ts-node -r tsconfig-paths/register",
    "lint": "./scripts/lint"
  },
  "devDependencies": {
    "@arethetypeswrong/cli": "^0.18.3",
    "@aws-sdk/credential-provider-node": "^3.972.47",
    "@smithy/hash-node": "^4.3.5",
    "@smithy/signature-v4": "^5.4.5",
    "@swc/core": "^1.3.102",
    "@swc/jest": "^0.2.29",
    "@types/jest": "^30.0.0",
    "@types/node": "^26.2.0",
    "@types/ws": "^8.5.13",
    "@types/yargs": "^17.0.35",
    "deep-object-diff": "^1.1.9",
    "execa": "^5.1.1",
    "fast-check": "^4.9.0",
    "fast-glob": "^3.3.2",
    "google-auth-library": "^11.3.1",
    "iconv-lite": "^0.7.3",
    "jest": "^30.4.2",
    "oxfmt": "0.72.0",
    "oxlint": "1.87.0",
    "p-all": "^3.0.0",
    "publint": "^0.3.22",
    "signal-exit": "^4.1.0",
    "superstruct": "^2.0.2",
    "ts-jest": "^29.1.0",
    "ts-node": "^10.5.0",
    "tsconfig-paths": "^4.0.0",
    "tslib": "^2.8.1",
    "typescript": "6.0.3",
    "typescript-4-9": "npm:typescript@4.9.5",
    "ultracite": "7.11.1",
    "undici": "8.12.2",
    "vitest": "5.0.5",
    "ws": "^8.21.0",
    "yargs": "^18.1.0",
    "zod": "^3.25 || ^4.0"
  },
  "overrides": {
    "minimatch": "^9.0.9"
  },
  "imports": {
    "#x509-transport-state": {
      "types": "./src/internal/auth/x509-transport-state.cts",
      "browser": "./src/internal/auth/x509-transport-state-browser.ts",
      "node": "./src/internal/auth/x509-transport-state.cts",
      "default": "./src/internal/auth/x509-transport-state-browser.ts"
    }
  },
  "exports": {
    ".": {
      "import": "./dist/index.mjs",
      "require": "./dist/index.js"
    },
    "./auth": {
      "import": "./dist/auth/index.mjs",
      "require": "./dist/auth/index.js"
    },
    "./internal/auth/x509-transport-capability": null,
    "./internal/auth/x509-transport-capability.js": null,
    "./internal/auth/x509-transport-capability.mjs": null,
    "./internal/auth/x509-transport-registry": null,
    "./internal/auth/x509-transport-registry.js": null,
    "./internal/auth/x509-transport-registry.mjs": null,
    "./internal/auth/x509-credential-options": null,
    "./internal/auth/x509-credential-options.js": null,
    "./internal/auth/x509-credential-options.mjs": null,
    "./internal/auth/x509-api-origin": null,
    "./internal/auth/x509-api-origin.js": null,
    "./internal/auth/x509-api-origin.mjs": null,
    "./internal/auth/x509-transport-state": null,
    "./internal/auth/x509-transport-state.cjs": null,
    "./internal/auth/x509-transport-state.js": null,
    "./internal/auth/x509-transport-state.mjs": null,
    "./internal/auth/x509-transport-state-browser": null,
    "./internal/auth/x509-transport-state-browser.js": null,
    "./internal/auth/x509-transport-state-browser.mjs": null,
    "./*.mjs": {
      "default": "./dist/*.mjs"
    },
    "./*.js": {
      "default": "./dist/*.js"
    },
    "./*": {
      "import": "./dist/*.mjs",
      "require": "./dist/*.js"
    }
  },
  "peerDependencies": {
    "@aws-sdk/credential-provider-node": ">=3.972.0 <4",
    "@smithy/hash-node": ">=4.3.0 <5",
    "@smithy/signature-v4": ">=5.4.0 <6",
    "google-auth-library": ">=9.15.1 <12",
    "undici": ">=5 <9",
    "ws": "^8.21.0",
    "zod": "^3.25 || ^4.0"
  },
  "peerDependenciesMeta": {
    "@aws-sdk/credential-provider-node": {
      "optional": true
    },
    "@smithy/hash-node": {
      "optional": true
    },
    "@smithy/signature-v4": {
      "optional": true
    },
    "google-auth-library": {
      "optional": true
    },
    "undici": {
      "optional": true
    },
    "ws": {
      "optional": true
    },
    "zod": {
      "optional": true
    }
  }
}
